test('トップページ', async ({ page }) => {
  await page.goto('/');
  await expect(page.getByRole('heading', { name: 'ホーム' })).toBeVisible();
});

test.describe('ログイン', () => {
  test('フォーム表示', async ({ page }) => {
    await page.goto('/login');
    await expect(page.getByLabel('メール')).toBeVisible();
  });
});

test.beforeEach(async ({ page }) => {
  await page.goto('/');
});

test.afterEach(async ({ page }, testInfo) => {
  if (testInfo.status !== testInfo.expectedStatus) {
    await testInfo.attach('failure', {
      body: await page.screenshot(),
      contentType: 'image/png'
    });
  }
});

await test.step('フォーム入力', async () => {
  await page.getByLabel('メール').fill('pomo@example.com');
});

const card = page.getByTestId('card').filter({
  has: page.getByRole('heading', { name: 'Pomo', exact: true })
});

const popupPromise = page.waitForEvent('popup');
await page.getByRole('link', { name: '詳細' }).click();
const popup = await popupPromise;
await expect(popup).toHaveURL(/detail/);

const downloadPromise = page.waitForEvent('download');
await page.getByRole('button', { name: 'CSV出力' }).click();
const download = await downloadPromise;
await download.saveAs(testInfo.outputPath(download.suggestedFilename()));

await expect.poll(async () => {
  const response = await request.get('/api/status');
  const body = await response.json();
  return body.state;
}).toBe('ready');

const responsePromise = page.waitForResponse(r => r.url().endsWith('/api/users') &&
  r.request().method() === 'POST');
await page.getByRole('button', { name: '保存' }).click();
const response = await responsePromise;
expect(response.ok()).toBeTruthy();

